for (const [cardValue, count] of Object.entries(myCards)) {
	if (count < 4) {
		runtime.callFunction('disableCardsOutlineByValue', cardValue);	
	}
}

for (const [cardValue, count] of Object.entries(myCards)) {
	if (count >= 4) {
		runtime.callFunction('enableCardsOutlineByValue', cardValue);	
	}
}

